-- Jeu de données synthétique : 12 utilisateurs, 1000 tablées réparties
-- dans Lyon et les communes voisines, avec participations, apports et messages.
-- Idempotent : purge les lignes synt.%@labonnetablee.test avant insertion.
-- Application : executer chaque fichier dans l ordre avec npx wrangler d1 execute labonnetablee-db --remote --file=seed/<fichier>

DELETE FROM messages WHERE tableId IN (SELECT id FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test'));

DELETE FROM contributions WHERE participationId IN (SELECT p.id FROM participations p WHERE p.tableId IN (SELECT id FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test')) OR p.userId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test'));

DELETE FROM idempotency_keys WHERE participationId IN (SELECT p.id FROM participations p WHERE p.tableId IN (SELECT id FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test')) OR p.userId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test'));

DELETE FROM participations WHERE tableId IN (SELECT id FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test')) OR userId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test');

DELETE FROM tables WHERE hostId IN (SELECT id FROM users WHERE email LIKE 'synt.%@labonnetablee.test');

DELETE FROM users WHERE email LIKE 'synt.%@labonnetablee.test';


